\begin{align*}
 \| v \|_{\Theta_h(T_1,t)}^2 &\lesssim  \| \jump{v}_{\omega_F^h} \|_{\Theta_h(T_1,t)}^2 + \| v\|_{\Theta_h(T_2,t)}^2, 
 \\
 \| \nabla v \|_{\Theta_h(T_1,t)}^2 &\lesssim  \frac{1}{h^2} \| \jump{v}_{\omega_F^h} \|_{\Theta_h(T_1,t)}^2 + \| \nabla v\|_{\Theta_h(T_2,t)}^2 
 \nonumber
\end{align*}
 };

 \node[text width=\dissorpaper{6.3cm}{6cm}, draw] (gp_E_I_box) at (20, -6) { \Cref{lemma_gp_E_IpGP}: $\forall u \in W_h$ \vspace{-0.25cm} \begin{align*}
  \|u\|^2_{\EQhn} &\lesssim \frac{h^2}{\gamma_J} j^n_h(u,u) + \| u \|_{\IQhn}^2, \\ 
 \|\nabla u\|^2_{\EQhn} &\lesssim \frac{1}{\gamma_J} j^n_h(u,u) + \| \nabla u \|_{\IQhn}^2 
\end{align*}};

 \draw [->] (gpassumpt.270) to ($(gp_E_I_box.150)!(gpassumpt.270)!(gp_E_I_box.140)$);

 \node[text width=\dissorpaper{6cm}{5.5cm}, draw] at (31, -6) (gp_bnd_t_box) {\Cref{lemma_bound_tn_ag_temporal_vol}: $\forall u \in W_h$\vspace{-0.25cm}
\begin{align*}
 &(u^{n-1}_+, u^{n-1}_+)_{\Omega^{h}(t_{n-1}^+)} + (u^n_-, u^n_-)_{\Omega^{h}(t_n^-)} \nonumber \\
 &~~ \lesssim \frac{1}{\Delta t} \left( \frac{h^2}{\gamma_J} j^n_h(u,u) + \|u\|_{\IQhn}^2 \right) 
\end{align*}};

\node[text width=\dissorpaper{9.3cm}{8.5cm}, draw] at (11,-9.5) (gp_derivs_box) {\Cref{lemma_temporal_inverse_ineq_gp}: $\forall u \in W_h$ \vspace{-0.25cm} \begin{align*}
 \Delta t (\partial_t^\Theta u, \partial_t^\Theta u)_{\Qhn} &\lesssim \frac{1}{\Delta t} \left( \frac{h^2}{\gamma_J} j^n_h(u,u) + \| u \|_{\IQhn}^2 \right), \\% \label{eq_temporal_inverse_ineq_gp}
 \Delta t (\nabla \partial_t^\Theta u, \nabla \partial_t^\Theta u)_{\Qhn} &\lesssim \frac{1}{\Delta t} \left( \frac{1}{\gamma_J} j^n_h(u,u) + \| \nabla u \|_{\IQhn}^2 \right). 
\end{align*} };

