\node[text width=\dissorpaper{10.5cm}{9.5cm}, draw] (stra_ineq_box) at (10,-12.5){\Cref{stra_ineq_stronger}, \Cref{stra_ineq} (Special trace inequality): $\forall u \in W_h$ \vspace{-0.25cm}
\begin{equation}
 \int_0^T \mathrm{d}t \, \int_{\partial \Omega^{h}(t)} \, u(t)^2 \lesssim \| \nabla u \|_{Q^h}^2 + \Delta t^2 \| \partial_t^\Theta u\|_{Q^h}^2 + \Delta t \clrem{I(u,u)} \lesssim \tripplenorm{u}^2. \nonumber
\end{equation} };

\node[text width=\dissorpaper{10.cm}{9.5cm}, draw] (B_Bmc_diff_box) at (27.75, -12){\Cref{lemma_B_Bmc_diff} (Mass conservation form mismatch): $\forall u,v$ \vspace{-0.3cm} \begin{equation}
  | B(u,v) - B_{mc}(u,v)| \lesssim \left(h^{q_s} + \Delta t^{q_t}\right) \left( \int_0^T \int_{\partial \Omega^h(t)} uv \, \mathrm{ds} \, \mathrm{d}t \right) \nonumber
\end{equation}};

\node[text width=\dissorpaper{7.2cm}{6.5cm}, draw] (symm_test_box) at (29.5, -14.5){\Cref{lemma_B_symmetric_testing_contrib} (symmetric testing): $\forall u \in W_h$ \vspace{-0.25cm}
\begin{align*}
  & ~~ B_h(u,u) + C_{\chi bl} \tripplenorm{u}_J^2 /2 \\

  \gtrsim & ~ \tripplejump{u}^2 + \| \nabla u \|_{Q^h}^2 - (h^{q_s} + \Delta t^{q_t}) \cdot \tripplenorm{u}^2. 
 \end{align*} };

\node[text width=\dissorpaper{11cm}{10cm}, draw] (stab_box) at (18,-18.75) { \Cref{thm:inf-sup} (Inf-Sup-stability): For all $u \in W_h$, $\exists \tilde v(u) \in W_h$ s.t. \vspace{-0.25cm}
\begin{equation*}
 B(u, \tilde v(u)) + J(u, \tilde v(u)) + K \cdot I(u, \tilde v(u)) \geq C_{\textrm{stab}} \tripplenorm{u}_j \cdot \tripplenorm{\tilde v(u)}_j.
\end{equation*}
};

 \node[text width=\dissorpaper{12.9cm}{12.25cm}, draw] (lem_p37_box) at (12,-16.){\Cref{lemma_P37}: $\exists C_{\ref{lemma_P37}}$, independent of $h$ and $\Delta t$, such that $\forall u \in W_h$, \vspace{-0.15cm}
\begin{align*}
 &B(u, \tilde\Pi(\Delta t \partial_t^\Theta u)) + J(u, \tilde\Pi (\Delta t \partial_t^\Theta u)) + K \cdot I(u, \tilde\Pi(\Delta t \partial_t^\Theta u)) \geq \\ 
 &\frac{1}{2} \sum_{n=1}^N \Delta t (\partial_t^\Theta u, \partial_t^\Theta u)_{\Qhn} - C_{\ref{lemma_P37}}  \left( \tripplejump{u}^2
 + \sum_{n=1}^N (\nabla u, \nabla u)_{\Qhn} + \tripplenorm{u}_J^2 + K \cdot \clrem{I(u,u)}\right) \nonumber
\end{align*}
};

